const llmOut = $input.first().json || {};
let query = '';
try { query = String($('When Executed by Another Workflow').first().json.query || ''); } catch (e) {}
if (!query) query = String(llmOut.query || '');

const texto_bruto = String(llmOut.output || llmOut.text || '');
const fuente = query + '\n' + texto_bruto;

function parseNumList(raw) {
  if (raw == null) return [];
  let s = String(raw).trim();
  s = s.replace(/^\s*\[/, '').replace(/\]\s*$/, '');
  return s.split(',').map(v => {
    v = v.trim().replace(/^["'`]|["'`]$/g, '');
    const n = Number(v);
    return (v !== '' && !isNaN(n)) ? n : null;
  }).filter(n => n !== null);
}

function findArray(patterns) {
  for (const p of patterns) {
    const re = new RegExp(p + '\\s*[:=]\\s*(\\[[^\\]]*\\]|[0-9.,\\s\\-]+)', 'i');
    const m = fuente.match(re);
    if (m) {
      const arr = parseNumList(m[1]);
      if (arr.length >= 2) return arr;
    }
  }
  return null;
}

function findHours() {
  const labeled = fuente.match(/(?:etiquetas|horas|periodos?|times?)\s*[:=]\s*([^\n]+)/i);
  if (labeled) {
    const parts = labeled[1].replace(/[\[\]]/g, '').split(',').map(x => x.trim()).filter(Boolean);
    const hours = parts.map(x => {
      const hm = x.match(/(\d{1,2}):(\d{2})/);
      return hm ? (String(hm[1]).padStart(2,'0') + ':' + hm[2]) : x;
    });
    if (hours.length >= 2) return hours;
  }
  const hours = [];
  const re = /\b(\d{1,2}):00\b/g;
  let m;
  while ((m = re.exec(fuente)) !== null) {
    const h = String(m[1]).padStart(2,'0') + ':00';
    if (!hours.includes(h)) hours.push(h);
  }
  return hours.length >= 2 ? hours : null;
}

const etiquetas = findHours() || ['11:00','12:00','13:00','14:00','15:00','16:00','17:00','18:00','19:00','20:00','21:00','22:00','23:00'];

const viento = findArray([
  'corrientes_viento',
  'viento_sfc',
  'viento\\s*sfc',
  'viento\\s*950\\s*hpa',
  'viento\\s*10m',
  'wind_speed',
  'velocidad_viento',
  'viento'
]) || findArray(['viento\\s*850\\s*hpa']);

const direccion = findArray([
  'viento_direccion',
  'direccion_viento',
  'dir_viento',
  'wind_dir',
  'direccion\\s*950'
]);

const nubosidad = findArray([
  'nubosidad',
  'cloudcover',
  'cobertura',
  'nubes'
]);

const temp = findArray([
  'temperatura_altitud',
  'temperatura',
  'temp_c',
  'temperature'
]);

const vis = findArray(['visibilidad_km', 'visibilidad', 'visibility']);

function align(arr) {
  if (!arr) return null;
  const n = Math.min(arr.length, etiquetas.length);
  if (n < 2) return null;
  return arr.slice(0, n);
}

const series = {};
const v = align(viento); if (v) series.corrientes_viento = v;
const d = align(direccion); if (d) series.viento_direccion = d;
const nu = align(nubosidad); if (nu) series.nubosidad = nu;
const t = align(temp); if (t) series.temperatura_altitud = t;
const vi = align(vis); if (vi) series.visibilidad_km = vi;

const seriesLens = Object.values(series).map(a => a.length);
const labLen = seriesLens.length ? Math.max.apply(null, seriesLens) : 2;
const labs = etiquetas.slice(0, Math.max(labLen, 2));

let reporte = texto_bruto.replace(/\[MOSTRAR_GRAFICO\][\s\S]*/i, '').trim();
if (!reporte) reporte = 'Análisis operativo generado. Gráfico construido desde datos meteorológicos.';

let chartBlock = '';
if (Object.keys(series).length) {
  const icao = (fuente.match(/\b(SACO|SAEZ|SAWH|SAAR|SABE|[A-Z]{4})\b/) || [])[0] || 'S/D';
  const ubi = (fuente.match(/Bariloche|Ezeiza|Ushuaia|[\wáéíóúÁÉÍÓÚñÑ]+,\s*Argentina/i) || [])[0] || 'Argentina';
  const lines = [
    '[MOSTRAR_GRAFICO]',
    'chart_type: line',
    'etiquetas: ' + labs.join(', '),
    'aeropuerto_origen: ' + icao,
    'ubicacion: ' + ubi
  ];
  for (const k of Object.keys(series)) {
    lines.push(k + ': ' + series[k].join(', '));
  }
  chartBlock = lines.join('\n');
} else if (/\[MOSTRAR_GRAFICO\]/i.test(texto_bruto)) {
  chartBlock = (texto_bruto.match(/\[MOSTRAR_GRAFICO\][\s\S]*/i) || [''])[0];
}

const output = chartBlock ? (reporte + '\n\n' + chartBlock).trim() : texto_bruto;

const extraerTexto = (campo, fallback) => {
  const regex = new RegExp(campo + '[:\\s]+([^\\n]+)', 'i');
  const match = output.match(regex);
  return match ? match[1].trim().split(',')[0].trim() : fallback;
};
const extraerPrimerNumero = (campo, fallback) => {
  const texto = extraerTexto(campo, '');
  if (!texto) return fallback;
  const n = parseFloat(String(texto).replace(',', '.'));
  return Number.isFinite(n) ? n : fallback;
};

const aeropuerto_origen = extraerTexto('aeropuerto_origen', 'Origen no especificado');
const aeropuerto_destino = extraerTexto('aeropuerto_destino', 'Destino no especificado');
const velocidadViento = (series.corrientes_viento && series.corrientes_viento[0]) || extraerPrimerNumero('corrientes_viento', 0);
const direccionViento = (series.viento_direccion && series.viento_direccion[0]) || null;
const altitudRef = extraerPrimerNumero('altitud_vuelo', 10000);

return [{
  json: {
    timestamp: new Date().toISOString(),
    session_id: llmOut.session_id || ('aereo-' + Date.now()),
    sector: 'AEREO',
    aeropuerto_origen,
    aeropuerto_destino,
    altitud_vuelo: altitudRef,
    temperatura_altitud: (series.temperatura_altitud && series.temperatura_altitud[0]) || 15,
    corrientes_viento: {
      velocidad: velocidadViento,
      direccion: (direccionViento != null && Number.isFinite(direccionViento)) ? direccionViento : 'variable',
      altitud: altitudRef
    },
    visibilidad_km: (series.visibilidad_km && series.visibilidad_km[0]) || 10,
    condiciones_atmosfericas: extraerTexto('condiciones_atmosfericas', 'Sin datos'),
    ai_flight_analysis: reporte,
    metadata: JSON.stringify({ status: 'success', chart_from: Object.keys(series).length ? 'query' : 'llm' }),
    output,
    chart_block: chartBlock
  }
}];
